<script setup lang="ts">
import { computed,ref } from 'vue'
import PageHeader from '../components/layout/PageHeader.vue'
import DataTable from '../components/table/DataTable.vue'
import Toast from '../components/common/Toast.vue'
import { useTaskStore } from '../stores/taskStore'
import { useSimpleFlowStore } from '../stores/simpleFlowStore'
import { pairRows } from '../services/simplePipeline'
import { downloadJSON } from '../utils/download'
import { exportTable } from '../utils/tableExport'
import type { TableFormat } from '../utils/tableExport'
import { downloadVillageArchive } from '../utils/villageExcel'
import { villageVector } from '../services/villageExport'
import type { VillageGroup } from '../services/villageExport'
const task=useTaskStore(),flow=useSimpleFlowStore(),message=ref(''),detail=ref<Record<string,unknown>|null>(null)
const format=ref<TableFormat>('xlsx')
const isVillage=computed(()=>task.activeId==='village-boundary'),villageFilter=ref('')
const rows=computed(()=>flow.output?pairRows(flow.output):[]),columns=computed(()=>flow.output?.template.columns.map(c=>({key:c.key,label:c.header}))||[])
const displayRows=computed(()=>isVillage.value&&villageFilter.value?flow.villageGroups.groups.find(g=>g.key===villageFilter.value)?.rows||[]:rows.value)
function oneVillage(group:VillageGroup){try{if(flow.output)exportTable(group.rows,flow.output.template,format.value,group.fileStem)}catch(e){message.value=String(e)}}
function oneVector(group:VillageGroup){if(flow.output)downloadJSON(villageVector(flow.output,group),`${group.fileStem}.geojson`)}
function vector(){if(flow.output)downloadJSON(flow.output.geojson,`${task.profile.name}_标准矢量.geojson`)}
function excel(){try{if(!flow.output)return;if(isVillage.value){if(flow.villageGroups.errors.length)throw new Error(flow.villageGroups.errors[0]);downloadVillageArchive(flow.villageGroups.groups,flow.output.template,format.value);message.value=`已生成 ${flow.villageGroups.groups.length} 个独立 ${format.value.toUpperCase()} 村表，打包为 ZIP。`}else exportTable(rows.value,flow.output.template,format.value,`${task.profile.name}_导入表格`)}catch(e){message.value=String(e)}}
</script>
<template><PageHeader title="矢量和表格已就绪" description="下载处理后的矢量和表格。未映射字段留空，模板列顺序不变。"><RouterLink class="button secondary" to="/mapping">返回调整映射</RouterLink></PageHeader><section v-if="!flow.output" class="panel empty"><h2>还没有生成结果，或映射已修改</h2><p>请完成映射和拓扑检查，再生成矢量与表格。刷新后需重新上传。</p><RouterLink class="button" to="/mapping">前往处理 →</RouterLink></section><template v-else><div class="function-context"><span>{{task.profile.name}} · {{flow.fileName}}</span><span>{{rows.length}} 个要素 · {{columns.length}} 个完整字段</span></div><div class="home-bottom"><section class="panel output-card"><h2>标准字段矢量</h2><p>GeoJSON 格式，保留原始几何和完整模板字段。</p><button @click="vector">下载矢量 ↓</button></section><section class="panel output-card"><h2>{{isVillage?'每村一个表格':'对应模板表格'}}</h2><p>{{isVillage?`按村分成 ${flow.villageGroups.groups.length} 个独立 ${format.toUpperCase()} 文件，打包下载；每张表保留22列模板字段。`:'按模板顺序导出，支持 Excel 和 CSV。'}}</p><label class="table-format">表格格式 <select v-model="format" aria-label="表格导出格式"><option value="xlsx">Excel（.xlsx）</option><option value="csv">CSV（UTF-8 BOM）</option></select></label><p v-if="format==='csv'" class="hint">CSV 仅含一行完整字段表头，空值留空。编码前导零在文件中保留；用 Excel 打开时，建议通过“从文本/CSV”导入并将编码列设为文本。</p><button @click="excel">{{isVillage?'批量下载各村表格 ZIP ↓':'下载表格 ↓'}}</button></section></div><Toast :message="message"/><section v-if="isVillage" class="panel"><div class="section-heading"><div><h2>逐村下载</h2><p>一个村对应一个 {{format.toUpperCase()}} 文件；逐村下载与批量下载使用上方选择的格式。</p></div><span class="badge neutral">{{flow.villageGroups.groups.length}} 个村</span></div><div class="table-scroll"><table><thead><tr><th>村名</th><th>村标识</th><th>要素数</th><th>独立成果</th></tr></thead><tbody><tr v-for="g in flow.villageGroups.groups" :key="g.key"><td>{{g.name}}</td><td>{{g.key}}</td><td>{{g.rows.length}}</td><td><div class="button-row"><button class="secondary small" @click="oneVillage(g)">下载该村表格</button><button class="text-button" @click="oneVector(g)">下载该村矢量</button></div></td></tr></tbody></table></div></section><div class="notice" v-if="flow.report?.issues.length">生成时存在 {{flow.report.issues.length}} 项拓扑警告，几何已原样保留。<button class="text-button" @click="downloadJSON(flow.report,'拓扑检查报告.json')">下载检查报告</button></div><section class="panel"><div class="section-heading"><h2>{{isVillage?'各村属性预览':'数据预览'}}</h2><select v-if="isVillage" v-model="villageFilter" aria-label="按村预览"><option value="">预览全部村</option><option v-for="g in flow.villageGroups.groups" :key="g.key" :value="g.key">{{g.name}} · {{g.key}}</option></select><span class="badge neutral">空值显示为 —</span></div><DataTable :columns="columns" :rows="displayRows" @select="detail=$event"/></section></template><div v-if="detail" class="modal-backdrop" @click.self="detail=null"><section class="modal"><div class="section-heading"><h2>属性详情</h2><button class="secondary" @click="detail=null">关闭</button></div><pre class="vector-json">{{flow.output?.geojson.features.find(f=>String(f.id)===detail?.rowId)?.properties}}</pre></section></div></template>
